#include <bits/stdc++.h>
using namespace std;
int main(){
    int n,t;
    if(!(cin>>n>>t))return 0;
    static long long dp[21][5][5][12][12];
    memset(dp,0,sizeof(dp));
    for(int a=1;a<=4;a++)for(int b=1;b<=4;b++) if(a!=b) dp[2][a][b][0][0]=1;
    for(int i=2;i<n;i++){
        for(int a=1;a<=4;a++)for(int b=1;b<=4;b++)for(int h=0;h<=t;h++)for(int v=0;v<=t;v++){
            long long cur=dp[i][a][b][h][v];
            if(!cur)continue;
            for(int c=1;c<=4;c++){
                if(c==b)continue;
                int nh=h,nv=v;
                if(a<b&&b>c)nh++;
                if(a>b&&b<c)nv++;
                if(nh>t||nv>t)continue;
                dp[i+1][b][c][nh][nv]+=cur;
            }
        }
    }
    long long ans=0;
    if(t>=1){
        for(int a=1;a<=4;a++)for(int b=1;b<=4;b++) ans+=dp[n][a][b][t][t-1];
    }
    cout<<ans<<endl;
    return 0;
}
